using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders; using TP_ControlVehicular.Entidad;
namespace TP_ControlVehicular.Datos.Configuracion;
public class UsuarioConfiguration : IEntityTypeConfiguration<Usuario> { public void Configure(EntityTypeBuilder<Usuario> b) { b.ToTable("Usuario"); b.HasKey(x=>x.IdUsuario); b.Property(x=>x.IdUsuario).HasColumnName("id_usuario"); b.Property(x=>x.IdRol).HasColumnName("id_rol"); b.Property(x=>x.Nombre).HasColumnName("nombre").HasMaxLength(100).IsRequired(); b.Property(x=>x.Contrasena).HasColumnName("contrasena").HasMaxLength(250).IsRequired(); b.Property(x=>x.Estado).HasColumnName("estado").IsRequired(); b.HasOne(x=>x.Rol).WithMany(x=>x.Usuarios).HasForeignKey(x=>x.IdRol).OnDelete(DeleteBehavior.Restrict); } }
